window.__OPENSTAX_PHYSICS__[15] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.783Z","number":15,"code":"ch15","slug":"light","title":"Light","titleVi":"Ánh Sáng & Quang Phổ Điện Từ (Light & EM Spectrum)","sections":[{"uid":"hsphys.ch15.sec00","moduleId":"m54336","number":"15.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch15.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["The beauty of a coral reef, the warm radiance of sunshine, the sting of sunburn, the X-ray revealing a broken bone, even microwave popcorn—all are brought to us by electromagnetic waves. The list of the various types of electromagnetic waves, ranging from radio transmission waves to nuclear gamma-ray (γ-ray) emissions, is interesting in itself.","Even more intriguing is that all of these different phenomena are manifestations of the same thing—electromagnetic waves (see [Figure 15.0]). What are electromagnetic waves? How are they created, and how do they travel? How can we understand their widely varying properties? What is the relationship between electric and magnetic effects? These and other questions will be explored."],"figures":[{"sourceId":"fs-id1167064848846","filename":"CNX_HSPhysics_15_00_Coralreef.jpg","relativePath":"media/CNX_HSPhysics_15_00_Coralreef.jpg","alt":"The figure is a photograph of small, colorful fish swimming around a coral reef."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch15.sec01","moduleId":"m54342","number":"15.1","slug":"the-electromagnetic-spectrum","title":"The Electromagnetic Spectrum","isIntroduction":false,"learningObjectives":["Define the electromagnetic spectrum, and describe it in terms of frequencies and wavelengths","Describe and explain the differences and similarities of each section of the electromagnetic spectrum and the applications of radiation from those sections"],"bilingualGuide":{"notebookSummaryVi":"Bản chất Sóng điện từ (c = f·λ = 3.00 × 10⁸ m/s) và 7 vùng của Thang sóng điện từ (Radio → Gamma).","wordProblemCues":[{"phraseEn":"visible light spectrum","meaningVi":"Ánh sáng nhìn thấy (λ từ ~400 nm Tím đến ~700 nm Đỏ)","mathNotation":"400–700 nm"}],"commonTrapsVi":["Tất cả các sóng điện từ (từ sóng Radio đến tia Gamma) đều truyền trong chân không với CÙNG một tốc độ c = 3.00 × 10⁸ m/s!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch15.sec01.sub01","title":"The Electromagnetic Spectrum","summaryVi":null,"paragraphs":["We generally take light for granted, but it is a truly amazing and mysterious form of energy. Think about it: Light travels to Earth across millions of kilometers of empty space. When it reaches us, it interacts with matter in various ways to generate almost all the energy needed to support life, provide heat, and cause weather patterns. Light is a form of electromagnetic radiation (EMR) . The term light usually refers to visible light , but this is not the only form of EMR. As we will see, visible light occupies a narrow band in a broad range of types of electromagnetic radiation.","Electromagnetic radiation is generated by a moving electric charge, that is, by an electric current. As you will see when you study electricity, an electric current generates both an electric field , E , and a magnetic field , B . These fields are perpendicular to each other. When the moving charge oscillates, as in an alternating current, an EM wave is propagated. [Figure 15.1] shows how an electromagnetic wave moves away from the source—indicated by the ~ symbol.","This simulation demonstrates wave propagation. The EM wave is propagated from the broadcast tower on the left, just as in [Figure 15.1]. You can make the wave yourself or allow the animation to send it. When the wave reaches the antenna on the right, it causes an oscillating current. This is how radio and television signals are transmitted and received.","Where do radio waves fall on the electromagnetic spectrum?","From your study of sound waves, recall these features that apply to all types of waves:","As mentioned, electromagnetic radiation takes several forms. These forms are characterized by a range of frequencies. Because frequency is inversely proportional to wavelength, any form of EMR can also be represented by its range of wavelengths. [Figure 15.1] shows the frequency and wavelength ranges of various types of EMR. With how many of these types are you familiar?","Take a few minutes to study the positions of the various types of radiation on the EM spectrum, above. The narrow band that is visible light extends from lower-frequency red light to higher-frequency violet light. Frequencies just below the visible are called infrared (below red) and those just above are ultraviolet (beyond violet). Radio waves , which overlap with the frequencies used for media broadcasts of TV and radio signals, occupy frequencies even lower than infrared (IR). The microwave radiation that you see on the diagram is the same radiation that is used in a microwave oven. What we feel as radiant heat is also a form of low-frequency EMR. The high-frequency radiation to the right of ultraviolet (UV) includes X-rays and gamma (γ) rays.","The Scottish physicist James Clerk Maxwell (1831–1879) is regarded widely to have been the greatest theoretical physicist of the nineteenth century. Although he died young, Maxwell not only formulated a complete electromagnetic theory, represented by Maxwell’s equations , he also developed the kinetic theory of gases, and made significant contributions to the understanding of color vision and the nature of Saturn’s rings.","Maxwell brought together all the work that had been done by brilliant physicists, such as Ørsted, Coulomb, Ampere, Gauss, and Faraday, and added his own insights to develop the overarching theory of electromagnetism. Maxwell’s equations are paraphrased here in words because their mathematical content is beyond the level of this text. However, the equations illustrate how apparently simple mathematical statements can elegantly unite and express a multitude of concepts—why mathematics is the language of science.","Maxwell’s Equations","Maxwell’s complete theory shows that electric and magnetic forces are not separate, but different manifestations of the same thing—the electromagnetic force. This classical unification of forces is one motivation for current attempts to unify the four basic forces in nature—the gravitational, electromagnetic, strong nuclear, and weak nuclear forces. The weak nuclear and electromagnetic forces have been unified, and further unification with the strong nuclear force is expected; but, the unification of the gravitational force with the other three has proven to be a real head-scratcher.","One final accomplishment of Maxwell was his development in 1855 of a process that could produce color photographic images. In 1861, he and photographer Thomas Sutton worked together on this process. The color image was achieved by projecting red, blue, and green light through black-and-white photographs of a tartan ribbon, each photo itself exposed in different-colored light. The final image was projected onto a screen (see [Figure 15.1])."],"figures":[{"sourceId":"fs-id1167066103182","filename":"CNX_HSPhysics_15_01_EMwave.jpg","relativePath":"media/CNX_HSPhysics_15_01_EMwave.jpg","alt":"The diagram shows two intersecting planes: a vertical plane labeled “E” and a horizontal plane labeled “B”. The line of intersection is drawn as an arrow, with the letter “c” next to the arrowhead. Within the vertical plane are the crest, trough, and crest of a blue wave, enclosing arrows that point from the baseline to the line of the wave. Likewise, within the horizontal plane are the crest, trough, and crest of a red wave, enclosing arrows that point from the baseline to the line of the wave. To the left of the intersecting planes is a thin vertical bar with a small circle in the middle and a wave symbol within the circle."},{"sourceId":"fs-id1167065864505","filename":"CNX_HSPhysics_15_01_EMSpectrum-a267.jpg","relativePath":"media/CNX_HSPhysics_15_01_EMSpectrum-a267.jpg","alt":"This figure shows the electromagnetic spectrum between two parallel, horizontal lines. The lower line, labeled “Frequency (Hz)”, is calibrated in increments that increase by 100-fold, starting from 10 superscript 0 at the extreme left and ending beyond 10 superscript 24 on the extreme right. The upper line, labeled “Wavelength”, is calibrated in increments that decrease by 100-fold, starting from 3 times 10 superscript 6 on the left and ending with 3 times 10 superscript minus 14 on the right. Each wavelength measure has the unit “m” after it. The various categories of the spectrum are written between the parallel lines, with a double-headed arrow showing the range of each category. Starting from the left, they are: “Radio waves”, “Infrared”, “Visible light”, “Ultraviolet”, “X rays”, and “gamma rays”. Within the range for “Radio waves” are the subcategories labeled as “AM radio”, “TV”, and “Microwaves”. Within the range for “TV” is the subcategory FM radio."},{"sourceId":"fs-id1167065761913","filename":"CNX_HSPhysics_15_01_FirstColor.jpg","relativePath":"media/CNX_HSPhysics_15_01_FirstColor.jpg","alt":"Photograph of a tartan ribbon tied like a bow."}],"tables":[]},{"uid":"hsphys.ch15.sec01.sub02","title":"Characteristics of Electromagnetic Radiation","summaryVi":null,"paragraphs":["All the EM waves mentioned above are basically the same form of radiation. They can all travel across empty space, and they all travel at the speed of light in a vacuum. The basic difference between types of radiation is their differing frequencies. Each frequency has an associated wavelength. As frequency increases across the spectrum, wavelength decreases. Energy also increases with frequency. Because of this, higher frequencies penetrate matter more readily. Some of the properties and uses of the various EM spectrum bands are listed in [Table_15_01].","The narrow band of visible light is a combination of the colors of the rainbow. [Figure 15.1] shows the section of the EM spectrum that includes visible light. The frequencies corresponding to these wavelengths are \\(4.0\\, \\times \\,{10}^{14}{\\text{s}}^{-1}\\) at the red end to \\(7.9\\, \\times \\,{10}^{14}{\\text{s}}^{-1}\\) at the violet end. This is a very narrow range, considering that the EM spectrum spans about 20 orders of magnitude.","As a child, you probably learned the color wheel, shown on the left in [Figure 15.1]. It helps if you know what color results when you mix different colors of paint together. Mixing two of the primary pigment colors—magenta, yellow, or cyan—together results in a secondary color. For example, mixing cyan and yellow makes green. This is called subtractive color mixing. Mixing different colors of light together is quite different. The diagram on the right shows additive color mixing. In this case, the primary colors are red, green, and blue, and the secondary colors are cyan, magenta, and yellow. Mixing pigments and mixing light are different because materials absorb light by a different set of rules than does the perception of light by the eye. Notice that, when all colors are subtracted, the result is no color, or black. When all colors are added, the result is white light. We see the reverse of this when white sunlight is separated into the visible spectrum by a prism or by raindrops when a rainbow appears in the sky.","This video demonstrates additive color and color filters. Try all the settings except Photons .","Humans have found uses for every part of the electromagnetic spectrum. We will take a look at the uses of each range of frequencies, beginning with visible light. Most of our uses of visible light are obvious; without it our interaction with our surroundings would be much different. We might forget that nearly all of our food depends on the photosynthesis process in plants, and that the energy for this process comes from the visible part of the spectrum. Without photosynthesis, we would also have almost no oxygen in the atmosphere.","The low-frequency, infrared region of the spectrum has many applications in media broadcasting. Television, radio, cell phone, and remote-control devices all broadcast and/or receive signals with these wavelengths. AM and FM radio signals are both low-frequency radiation. They are in different regions of the spectrum, but that is not their basic difference. AM and FM are abbreviations for amplitude modulation and frequency modulation . Information in AM signals has the form of changes in amplitude of the radio waves; information in FM signals has the form of changes in wave frequency .","Another application of long-wavelength radiation is found in microwave ovens. These appliances cook or warm food by irradiating it with EM radiation in the microwave frequency range. Most kitchen microwaves use a frequency of \\(2.45\\, \\times \\,{10}^{9}\\) Hz. These waves have the right amount of energy to cause polar molecules, such as water, to rotate faster. Polar molecules are those that have a partial charge separation. The rotational energy of these molecules is given up to surrounding matter as heat. The first microwave ovens were called Radaranges because they were based on radar technology developed during World War II.","Radar uses radiation with wavelengths similar to those of microwaves to detect the location and speed of distant objects, such as airplanes, weather formations, and motor vehicles. Radar information is obtained by receiving and analyzing the echoes of microwaves reflected by an object. The speed of the object can be measured using the Doppler shift of the returning waves. This is the same effect you learned about when you studied sound waves. Like sound waves, EM waves are shifted to higher frequencies by an object moving toward an observer, and to lower frequencies by an object moving away from the observer. Astronomers use this same Doppler effect to measure the speed at which distant galaxies are moving away from us. In this case, the shift in frequency is called the red shift , because visible frequencies are shifted toward the lower-frequency, red end of the spectrum.","Exposure to any radiation with frequencies greater than those of visible light carries some health hazards. All types of radiation in this range are known to cause cell damage. The danger is related to the high energy and penetrating ability of these EM waves. The likelihood of being harmed by any of this radiation depends largely on the amount of exposure. Most people try to reduce exposure to UV radiation from sunlight by using sunscreen and protective clothing. Physicians still use X-rays to diagnose medical problems, but the intensity of the radiation used is extremely low. [Figure 15.1] shows an X-ray image of a patient’s chest cavity.","One medical-imaging technique that involves no danger of exposure is magnetic resonance imaging (MRI). MRI is an important imaging and research tool in medicine, producing highly detailed two- and three-dimensional images. Radio waves are broadcast, absorbed, and reemitted in a resonance process that is sensitive to the density of nuclei, usually hydrogen nuclei—protons."],"figures":[{"sourceId":"fs-id1167065860796","filename":"CNX_HSPhysics_15_01_Visible.jpg","relativePath":"media/CNX_HSPhysics_15_01_Visible.jpg","alt":"This diagram focuses on the visible section of the electromagnetic spectrum. A horizontal arrow represents wavelengths of light decreasing from left to right. The arrow is calibrated with numbers ranging from 800 on the left to 300 on the right, and the line is labeled with the Greek letter lambda, followed by the letters n m in parentheses. Above the arrow is a colored band stretching from about 760 up to about 420. The band, labeled as “Visible light”, shows colors labeled as “Red”, “Orange”, “Yellow”, “Green”, “Blue”, and “Violet”. To the left of the band is a region labeled as “Infrared”, above the 800 mark. To the right of the band is a region labeled as “Ultraviolet”, above the 300 mark."},{"sourceId":"fs-id1167065860797","filename":"CNX_HSPhysics_15_01_Color.jpg","relativePath":"media/CNX_HSPhysics_15_01_Color.jpg","alt":"The figure shows two panels arranged side by side. Each panel consists of three overlapping circles, arranged such that the intersection of any two circles passes through the center of the third circle. The left panel, labeled “Pigment” at the top and “Subtractive color” at the bottom, has the three circles on a white background. The top circle is labeled “Y” and colored yellow; the bottom left circle is labeled “M” and colored magenta; the bottom right circle is labeled “C” and colored cyan. The areas of overlap of pairs of circles are colored red, dark blue, and green, and the area of overlap of all three circles is black. The right panel, labeled “Light” at the top and “Additive color” at the bottom, has the three circles on a black background. The top circle is labeled “R” and colored red; the bottom left circle is labeled “G” and colored green; the bottom right circle is labeled “B” and colored dark blue. The areas of overlap of pairs of circles are colored yellow, cyan, and magenta, and the area of overlap of all three circles is white."},{"sourceId":"fs-id1167066090874","filename":"CNX_HSPhysics_15_01_X-ray.jpg","relativePath":"media/CNX_HSPhysics_15_01_X-ray.jpg","alt":"This figure is an X-ray of a person's chest cavity. It includes the outlines of artificial heart valves, a pacemaker, and some wires."}],"tables":[{"sourceId":"Table_15_01","headers":["Types of EM Waves","Production","Applications","Life Sciences Aspect","Issues"],"rows":[["Radio and TV","Accelerating charges","Communications, remote controls","MRI","Requires controls for band use"],["Microwaves","Accelerating charges & thermal agitation","Communications, microwave ovens, radar","Deep heating","Cell phone use"],["Infrared","Thermal agitation & electronic transitions","Thermal imaging, heating","Absorption by atmosphere","Greenhouse effect"],["Visible Light","Thermal agitation & electronic transitions","All pervasive","Photosynthesis, human vision",""],["Ultraviolet","Thermal agitation & electronic transitions","Sterilization, slowing abnormal growth of cells","Vitamin D production","Ozone depletion, causes cell damage"],["X-rays","Inner electronic transitions & fast collisions","Medical, security","Medical diagnosis, cancer therapy","Causes cell damage"],["Gamma Rays","Nuclear decay","Nuclear medicine, security","Medical diagnosis, cancer therapy","Causes cell damage, radiation damage"]]}]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch15.sec01.feat01","type":"tip","title":"Tips for Success","text":"Wavelengths of visible light are often given in nanometers, nm. One nm equals \\({10}^{-9}\\) m. For example, yellow light has a wavelength of about 600 nm, or \\(6\\, \\times \\,{10}^{-7}\\) m.","images":[]},{"uid":"hsphys.ch15.sec01.feat02","type":"physics-in-action","title":"Animal Color Perception","text":"The physics of color perception has interesting links to zoology. Other animals have very different views of the world than humans, especially with respect to which colors can be seen. Color is detected by cells in the eye called cones . Humans have three cones that are sensitive to three different ranges of electromagnetic wavelengths. They are called red, blue, and green cones, although these colors do not correspond exactly to the centers of the three ranges. The ranges of wavelengths that each cone detects are red, 500 to 700 nm; green, 450 to 630 nm; and blue, 400 to 500 nm.\nMost primates also have three kinds of cones and see the world much as we do. Most mammals other than primates only have two cones and have a less colorful view of things. Dogs, for example see blue and yellow, but are color blind to red and green. You might think that simpler species, such as fish and insects, would have less sophisticated vision, but this is not the case. Many birds, reptiles, amphibians, and insects have four or five different cones in their eyes. These species don’t have a wider range of perceived colors, but they see more hues, or combinations of colors. Also, some animals, such as bees or rattlesnakes, see a range of colors that is as broad as ours, but shifted into the ultraviolet or infrared.\nThese differences in color perception are generally adaptations that help the animals survive. Colorful tropical birds and fish display some colors that are too subtle for us to see. These colors are believed to play a role in the species mating rituals. [Figure 15.1] shows the colors visible and the color range of vision in humans, bees, and dogs.\nHumans, bees, and dogs see colors differently. Dogs see fewer colors than humans, and bees see a different range of colors.\nThe belief that bulls are enraged by seeing the color red is a misconception. What did you read in this Links to Physics that shows why this belief is incorrect?\nBulls are color-blind to every color in the spectrum of colors.\nBulls are color-blind to the blue colors in the spectrum of colors.\nBulls are color-blind to the red colors in the spectrum of colors.\nBulls are color-blind to the green colors in the spectrum of colors.","images":[{"sourceId":"fs-id1167064853394","filename":"CNX_HSPhysics_15_01_DogBee.jpg","relativePath":"media/CNX_HSPhysics_15_01_DogBee.jpg","alt":"This figure shows three parallel, horizontal bands of colors, labeled “Humans”, “Bees”, and “Dogs”. Each band starts with the blue color on the left and ends with the red color on the right. Above the bands is a horizontal line calibrated with numbers ranging from 300 on the left to 700 on the right, and the line is labeled as “Wavelength”, followed by the letters n m in parentheses."}]}],"summaryPoints":["The electromagnetic spectrum is made up of a broad range of frequencies of electromagnetic radiation.","All frequencies of EM radiation travel at the same speed in a vacuum and consist of an electric field and a magnetic field. The types of EM radiation have different frequencies and wavelengths, and different energies and penetrating ability."],"glossary":[{"term":"electric field","termVi":"Điện trường (E)","definition":"a field that tells us the force per unit charge at all locations in space around a charge distribution","definitionVi":"Trường lực bao quanh điện tích, tác dụng lực lên các điện tích khác đặt trong nó.","memoryTipVi":"Trong sóng điện từ, E vuông góc với B và vuông góc phương truyền sóng."},{"term":"electromagnetic radiation (EMR)","termVi":"Bức xạ điện từ (Sóng điện từ)","definition":"radiant energy that consists of oscillating electric and magnetic fields","definitionVi":"Sóng ngang gồm điện trường và từ trường biến thiên vuông góc nhau, truyền được trong CHÂN KHÔNG với tốc độ c = 3.00 × 10⁸ m/s.","memoryTipVi":"Thang sóng điện từ từ bước sóng dài → ngắn: Radio → Microwave → Hồng ngoại → Ánh sáng thấy → Tử ngoại → Tia X → Tia Gamma."},{"term":"magnetic field","termVi":"Từ trường (B)","definition":"the directional lines around a magnetic material that indicates the direction and magnitude of the magnetic force","definitionVi":"Trường lực bao quanh nam châm hoặc dòng điện chuyển động.","memoryTipVi":"Biến thiên từ trường sinh ra điện trường và ngược lại."},{"term":"Maxwell’s equations","termVi":"Hệ phương trình Maxwell","definition":"equations that describe the interrelationship between electric and magnetic fields, and how these fields combine to form electromagnetic radiation","definitionVi":"4 phương trình nền tảng thống nhất Điện học, Từ học và chứng minh Ánh sáng chính là sóng điện từ.","memoryTipVi":"Một trong những thành tựu vĩ đại nhất lịch sử Vật lý."}],"assessments":[{"uid":"hsphys.ch15.sec01.q001","sourceId":"fs-id1167064758211","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Identify the fields produced by a moving charged particle.","images":[],"choices":[{"label":"a","text":"Both an electric field and a magnetic field will be produced."},{"label":"b","text":"Neither a magnetic field nor an electric field will be produced."},{"label":"c","text":"A magnetic field, but no electric field will be produced."},{"label":"d","text":"Only the electric field, but no magnetic field will be produced."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q006","sourceId":"fs-id1167065886179","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Use the concepts on which Maxwell’s equations are based to explain why a compass needle is deflected when the compass is brought near a wire that is carrying an electric current.","images":[],"choices":[{"label":"a","text":"The charges in the compass needle and the charges in the electric current have interacting electric fields, causing the needle to deflect."},{"label":"b","text":"The electric field from the moving charges in the current interacts with the magnetic field of the compass needle, causing the needle to deflect."},{"label":"c","text":"The magnetic field from the moving charges in the current interacts with the electric field of the compass needle, causing the needle to deflect."},{"label":"d","text":"The moving charges in the current produce a magnetic field that interacts with the compass needle’s magnetic field, causing the needle to deflect."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q007","sourceId":"fs-id1167065883530","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Consider these colors of light: yellow, blue, and red. Part A. Put these light waves in order according to wavelength, from shortest wavelength to longest wavelength. Part B. Put these light waves in order according to frequency, from lowest frequency to highest frequency.","images":[],"choices":[{"label":"a","text":"wavelength: blue, yellow, red\nfrequency: blue, yellow, red"},{"label":"b","text":"wavelength: red, yellow, blue\nfrequency: red, yellow, blue"},{"label":"c","text":"wavelength: red, yellow, blue\nfrequency: blue, yellow, red"},{"label":"d","text":"wavelength: blue, yellow, red\nfrequency: red, yellow, blue"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q008","sourceId":"eip-id1166849159403","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Describe the location of gamma rays on the electromagnetic spectrum.","images":[],"choices":[{"label":"a","text":"At the high-frequency and long-wavelength end of the spectrum"},{"label":"b","text":"At the high-frequency and short-wavelength end of the spectrum"},{"label":"c","text":"At the low-frequency and long-wavelength end of the spectrum"},{"label":"d","text":"At the low-frequency and short-wavelength end of the spectrum"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q009","sourceId":"eip-id1166851143808","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"In which region of the electromagnetic spectrum would you find radiation that is invisible to the human eye and has low energy?","images":[],"choices":[{"label":"a","text":"Long-wavelength and high-frequency region"},{"label":"b","text":"Long-wavelength and low-frequency region"},{"label":"c","text":"Short-wavelength and high-frequency region"},{"label":"d","text":"Short-wavelength and low-frequency region"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q010","sourceId":"fs-id1167066188831","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Standing in front of a fire, we can sense both its heat and its light. How are the light and heat radiated by the fire the same, and how are they different?","images":[],"choices":[{"label":"a","text":"Both travel as waves, but only light waves are a form of electromagnetic radiation."},{"label":"b","text":"Heat and light are both forms of electromagnetic radiation, but light waves have higher frequencies."},{"label":"c","text":"Heat and light are both forms of electromagnetic radiation, but heat waves have higher frequencies."},{"label":"d","text":"Heat and light are both forms of electromagnetic radiation, but light waves have higher wavelengths."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q011","sourceId":"fs-id1167064873292","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Light shines on a picture of the subtractive color wheel. The light is a mixture of red, blue, and green light.\nPart A—Which part of the color wheel will look blue? Explain in terms of absorbed and reflected light.\nPart B—Which part of the color wheel will look yellow? Explain in terms of absorbed and reflected light.\nThe blue section of the wheel will look blue because it will absorb blue light and reflect red and green.\nThe yellow section of the wheel will look yellow because it will absorb red and green light and reflect blue.\nThe yellow section of the wheel will look blue because it will absorb blue light and reflect red and green.\nThe blue section of the wheel will look yellow because it will absorb red and green light and reflect blue.\nThe blue section of the wheel will look blue because it will reflect blue light and absorb red and green.\nThe yellow section of the wheel will look yellow because it will reflect red and green light and absorb blue.","images":[],"choices":[{"label":"a","text":"The yellow section of the wheel will look blue because it will reflect blue light and absorb red and green."},{"label":"b","text":"The blue section of the wheel will look yellow because it will reflect red and green light and absorb blue."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q012","sourceId":"eip-id1166851091220","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Part A. When you stand in front of an open fire, you can sense light waves with your eyes. You sense another type of electromagnetic radiation as heat. What is this other type of radiation?\nPart B. How is this other type of radiation different front light waves?\nX-rays\nThe X-rays have lower frequencies and longer wavelengths than the light waves.\ninfrared rays\nThe infrared rays have higher frequencies and shorter wavelengths than the light waves.\ninfrared rays\nThe infrared rays have lower frequencies and longer wavelengths than the light waves.","images":[],"choices":[{"label":"a","text":"X-rays"},{"label":"b","text":"The X-rays have higher frequencies and shorter wavelengths than the light waves."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q013","sourceId":"eip-id1166851273599","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Overexposure to this range of EM radiation is dangerous, and yet it is used by doctors to diagnose medical problems.\nPart AIdentify the type of radiation.\nPart BLocate the position of this radiation on the EM spectrum by comparing its frequency and wavelength to visible light.\nPart CExplain why this radiation is both dangerous and therapeutic in terms of its energy, based on your answer to Part B.","images":[],"choices":[{"label":"a","text":"A. X-rays\nB. X-rays have shorter wavelengths (1 × 10 –8 – 5 × 10 –12 m) and higher frequencies (3 × 10 16 – 6 × 10 19 Hz) than visible light (7.5 × 10 –7 – 4.0 × 10 –7 m; 4.0 × 10 14 – 7.5 × 10 14 Hz).\nC. X-rays have low energies because of their high frequencies, and so can penetrate matter to greater depths."},{"label":"b","text":"A. X-rays\nB. X-rays have shorter wavelengths (1 × 10 –8 – 5 × 10 –12 m) and higher frequencies (3 × 10 10 – 6 × 10 13 Hz) than visible light (7.5 × 10 –7 – 4.0 × 10 –7 m; 4.0 × 10 14 – 7.5 × 10 14 Hz).\nC. X-rays have low energies because of their low frequencies, and so can penetrate matter to greater depths."},{"label":"c","text":"A. X-rays\nB. X-rays have longer wavelengths (1 × 10 –6 – 5 × 10 –7 m) and higher frequencies (3 × 10 15 – 6 × 10 15 Hz) than visible light (7.5 × 10 –7 – 4.0 × 10 –7 m; 4.0 × 10 14 – 7.5 × 10 14 Hz).\nC. X-rays have high energies because of their high frequencies, and therefore can penetrate matter to greater depths."},{"label":"d","text":"A. X-rays\nB. X-rays have shorter wavelengths (1 × 10 –8 – 5 × 10 –12 m) and higher frequencies (3 × 10 16 – 6 × 10 19 Hz) than visible light (7.5 × 10 –7 – 4.0 × 10 –7 m; 4.0 × 10 14 – 7.5 × 10 14 Hz).\nC. X-rays have high energies because of their high frequencies, and so can penetrate matter to greater depths."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q014","sourceId":"fs-id1167064743541","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which type of EM radiation has the shortest wavelengths?","images":[],"choices":[{"label":"a","text":"gamma rays"},{"label":"b","text":"infrared waves"},{"label":"c","text":"blue light"},{"label":"d","text":"microwaves"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q015","sourceId":"fs-id1167064937436","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which form of EM radiation has the most penetrating ability?","images":[],"choices":[{"label":"a","text":"red light"},{"label":"b","text":"microwaves"},{"label":"c","text":"gamma rays"},{"label":"d","text":"infrared radiation"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q018","sourceId":"fs-id1167064669924","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Describe one way in which heat waves—infrared radiation—are different from sound waves.","images":[],"choices":[{"label":"a","text":"Sound waves are transverse waves, whereas heat waves—infrared radiation—are longitudinal waves."},{"label":"b","text":"Sound waves have shorter wavelengths than heat waves."},{"label":"c","text":"Sound waves require a medium, whereas heat waves—infrared radiation—do not."},{"label":"d","text":"Sound waves have higher frequencies than heat waves."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q022","sourceId":"fs-id1167064818530","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A frequency of red light has a wavelength of 700 nm.\nPart A—Compare the wavelength and frequency of violet light to red light.\nPart B—Identify a type of radiation that has lower frequencies than red light.\nPart C—Identify a type of radiation that has shorter wavelengths than violet light.\nViolet light has a lower frequency and longer wavelength than red light.\ninfrared radiation\nultraviolet radiation\nViolet light has a higher frequency and shorter wavelength than red light.\nultraviolet radiation\ninfrared radiation\nViolet light has a higher frequency and shorter wavelength than red light.\ninfrared radiation\nultraviolet radiation","images":[],"choices":[{"label":"a","text":"Violet light has a lower frequency and longer wavelength than red light."},{"label":"b","text":"ultraviolet radiation"},{"label":"c","text":"infrared radiation"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec01.q023","sourceId":"fs-id1167064529146","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A mixture of red and green light is shone on each of the subtractive colors.\nPart A—Which of these colors of light are reflected from magenta?\nPart B—Which of these colors of light are reflected from yellow?\nPart C—Which these colors of light are reflected from cyan?","images":[],"choices":[{"label":"a","text":"Part A. red and green\nPart B. green\nPart C. red"},{"label":"b","text":"Part A. red and green\nPart B. red\nPart C. green"},{"label":"c","text":"Part A. green\nPart B. red and green\nPart C. red"},{"label":"d","text":"Part A. red\nPart B. red and green\nPart C. green"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":0,"subsectionCount":2,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":4,"assessmentCount":14}},{"uid":"hsphys.ch15.sec02","moduleId":"m54346","number":"15.2","slug":"the-behavior-of-electromagnetic-radiation","title":"The Behavior of Electromagnetic Radiation","isIntroduction":false,"learningObjectives":["Describe the behavior of electromagnetic radiation","Solve quantitative problems involving the behavior of electromagnetic radiation"],"bilingualGuide":{"notebookSummaryVi":"Độ rọi (Illuminance — định luật bình phương nghịch đảo 1/r²), Quang thông (Lumen) và Ánh sáng phân cực (Polarized Light).","wordProblemCues":[{"phraseEn":"inverse-square law of light","meaningVi":"Khoảng cách xa gấp đôi → Độ rọi giảm 4 lần","mathNotation":"E ∝ 1/r²"}],"commonTrapsVi":["Quang thông (Lumen) là đặc tính cố định của bóng đèn, còn Độ rọi (Lux) giảm nhanh khi ra xa bóng đèn."]},"keyEquations":[{"name":"frequency and wavelength","formula":"\\(c = f\\lambda\\)"},{"name":"illuminance","formula":"\\(\\text{illuminance =}\\,\\frac{P}{4\\pi {r}^{2}}\\)"}],"subsections":[{"uid":"hsphys.ch15.sec02.sub01","title":"Types of Electromagnetic Wave Behavior","summaryVi":null,"paragraphs":["In a vacuum, all electromagnetic radiation travels at the same incredible speed of 3.00 × 10 8 m/s, which is equal to 671 million miles per hour. This is one of the fundamental physical constants. It is referred to as the speed of light and is given the symbol c . The space between celestial bodies is a near vacuum, so the light we see from the Sun, stars, and other planets has traveled here at the speed of light. Keep in mind that all EM radiation travels at this speed. All the different wavelengths of radiation that leave the Sun make the trip to Earth in the same amount of time. That trip takes 8.3 minutes. Light from the nearest star, besides the Sun, takes 4.2 years to reach Earth, and light from the nearest galaxy—a dwarf galaxy that orbits the Milky Way—travels 25,000 years on its way to Earth. You can see why we call very long distances astronomical .","When light travels through a physical medium, its speed is always less than the speed of light. For example, light travels in water at three-fourths the value of c . In air, light has a speed that is just slightly slower than in empty space: 99.97 percent of c . Diamond slows light down to just 41 percent of c . When light changes speeds at a boundary between media, it also changes direction. The greater the difference in speeds, the more the path of light bends. In other chapters, we look at this bending, called refraction , in greater detail. We introduce refraction here to help explain a phenomenon called thin-film interference .","Have you ever wondered about the rainbow colors you often see on soap bubbles, oil slicks, and compact discs? This occurs when light is both refracted by and reflected from a very thin film. The diagram shows the path of light through such a thin film. The symbols n 1 , n 2 , and n 3 indicate that light travels at different speeds in each of the three materials. Learn more about this topic in the chapter on diffraction and interference.","[Figure 15.2] shows the result of thin film interference on the surface of soap bubbles. Because ray 2 travels a greater distance, the two rays become out of phase . That is, the crests of the two emerging waves are no longer moving together. This causes interference , which reinforces the intensity of the wavelengths of light that create the bands of color. The color bands are separated because each color has a different wavelength. Also, the thickness of the film is not uniform, and different thicknesses cause colors of different wavelengths to interfere in different places. Note that the film must be very, very thin—somewhere in the vicinity of the wavelengths of visible light.","You have probably experienced how polarized sunglasses reduce glare from the surface of water or snow. The effect is caused by the wave nature of light. Looking back at [Figure 15.1], we see that the electric field moves in only one direction perpendicular to the direction of propagation. Light from most sources vibrates in all directions perpendicular to propagation. Light with an electric field that vibrates in only one direction is called polarized . A diagram of polarized light would look like [Figure 15.1].","Polarized glasses are an example of a polarizing filter. These glasses absorb most of the horizontal light waves and transmit the vertical waves. This cuts down glare, which is caused by horizontal waves. [Figure 15.2] shows how waves traveling along a rope can be used as a model of how a polarizing filter works. The oscillations in one rope are in a vertical plane and are said to be vertically polarized. Those in the other rope are in a horizontal plane and are horizontally polarized. If a vertical slit is placed on the first rope, the waves pass through. However, a vertical slit blocks the horizontally polarized waves. For EM waves, the direction of the electric field oscillation is analogous to the disturbances on the ropes.","Light can also be polarized by reflection. Most of the light reflected from water, glass, or any highly reflective surface is polarized horizontally. [Figure 15.2] shows the effect of a polarizing lens on light reflected from the surface of water."],"figures":[{"sourceId":"fs-id1167067036714","filename":"CNX_HSPhysics_15_02_Thinfilm.jpg","relativePath":"media/CNX_HSPhysics_15_02_Thinfilm.jpg","alt":"This diagram shows three areas separated by two parallel, horizontal lines. The distance between the two lines is labeled “t”. The top area, labeled n subscript 1, has a white background. The middle area, labeled n subscript 2, has a hazy bluish background. The bottom area, labeled n subscript 3, has a hazy gray background. An arrow labeled “Incident light” starts from the top left of the white area, points in a southeasterly direction, and ends on the upper horizontal line. At that point, two arrows emerge: one of them, labeled number 1, travels back through the white area in the northeast direction; the other travels through the bluish area in a south-southeast direction until it reaches the lower horizontal line. At the point where the lower arrow ends, another arrow begins, pointing in the north-northeast direction until it reaches the upper horizontal line. From that junction, a new arrow emerges, labeled number 2, traveling in the white area and parallel to the arrow labeled number 1. A human eye observes the arrows marked 1 and 2."},{"sourceId":"fs-id1167063914916","filename":"CNX_HSPhysics_15_02_Rope.jpg","relativePath":"media/CNX_HSPhysics_15_02_Rope.jpg","alt":"This figure has two panels arranged side by side. The left panel, labeled “(a)”, shows a hand holding one end of a wave moving in a vertical plane and passing through a vertically oriented slit. Next to the hand is a double-headed vertical arrow labeled “Direction of polarization”. The right panel, labeled “(b)”, shows a hand holding one end of a wave moving in a horizontal plane and passing through a horizontally oriented slit. Next to the hand is a double-headed horizontal arrow labeled “Direction of polarization."},{"sourceId":"fs-id1167066983234","filename":"CNX_HSPhysics_15_02_Reflection.jpg","relativePath":"media/CNX_HSPhysics_15_02_Reflection.jpg","alt":"This figure shows two photographs arranged side by side. The left photograph, labeled “(a)”, shows a river bed that looks hazy because of interfering gray and white patches. The right photograph, labeled “(b)”, shows the same area of the river bed with almost no interfering gray patches, so that the pebbles on the bed are clearly visible."}],"tables":[]},{"uid":"hsphys.ch15.sec02.sub02","title":"Quantitative Treatment of Electromagnetic Waves","summaryVi":null,"paragraphs":["We can use the speed of light, c , to carry out several simple but interesting calculations. If we know the distance to a celestial object, we can calculate how long it takes its light to reach us. Of course, we can also make the reverse calculation if we know the time it takes for the light to travel to us. For an object at a very great distance from Earth, it takes many years for its light to reach us. This means that we are looking at the object as it existed in the distant past. The object may, in fact, no longer exist. Very large distances in the universe are measured in light years . One light year is the distance that light travels in one year, which is \\(9.46\\, \\times \\,{10}^{12}\\)\nkilometers or \\(5.88\\, \\times \\,{10}^{12}\\)\nmiles (…and 10 12 is a trillion!).","A useful equation involving c is","where f is frequency in Hz, and \\(\\lambda\\) is wavelength in meters.","The rate at which light is radiated from a source is called luminous flux , P , and it is measured in lumens (lm). Energy-saving light bulbs, which provide more luminous flux for a given use of electricity, are now available. One of these bulbs is called a compact fluorescent lamp ; another is an LED (light-emitting diode) bulb. If you wanted to replace an old incandescent bulb with an energy saving bulb, you would want the new bulb to have the same brightness as the old one. To compare bulbs accurately, you would need to compare the lumens each one puts out. Comparing wattage—that is, the electric power used—would be misleading. Both wattage and lumens are stated on the packaging.","The luminous flux of a bulb might be 2,000 lm. That accounts for all the light radiated in all directions. However, what we really need to know is how much light falls on an object, such as a book, at a specific distance. The number of lumens per square meter is called illuminance , and is given in units of lux (lx). Picture a light bulb in the middle of a sphere with a 1-m radius. The total surface of the sphere equals 4π r 2 m 2 . The illuminance then is given by","What happens if the radius of the sphere is increased 2 m? The illuminance is now only one-fourth as great, because the r 2 term in the denominator is 4 instead of 1. [Figure 15.2] shows how illuminance decreases with the inverse square of the distance."],"figures":[{"sourceId":"fs-id1167067038162","filename":"CNX_HSPhysics_15_02_Illuminanc.jpg","relativePath":"media/CNX_HSPhysics_15_02_Illuminanc.jpg","alt":"This diagram shows a small sphere on the left, labeled “Source of Electromagnetic Radiation”, and a series of arrows emerging from it, pointing rightward. Three curved surfaces are separated from the sphere by distances labeled as “r”, “2r”, and “3r”. One of these surfaces is labeled “Part of the surface of a sphere with radius r”. The arrows penetrate these three surfaces and move farther and farther apart as they move away from the sphere."}],"tables":[]},{"uid":"hsphys.ch15.sec02.sub03","title":"Performance Task","summaryVi":null,"paragraphs":["Design an experiment to observe the phenomenon of thin-film interference. Observe colors of visible light, and relate each color to its corresponding wavelength. Comparison with the magnitudes of visible light wavelength will give an appreciation of just how very thin a thin film is. Thin-film interference has a number of practical applications, such as anti-reflection coatings and optical filters. Thin films used in filters can be designed to reflect or transmit specific wavelengths of light. This is done by depositing a film one molecular layer at a time from a vapor, thus allowing the thickness of the film to be exactly controlled."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch15.sec02.ex01","number":"15.2.1","title":"Frequency and Wavelength Calculation","problem":"For example, you can calculate the frequency of yellow light with a wavelength of \\(6.00\\, \\times \\,{10}^{- 7}\\) m.","problemImages":[],"strategy":"Rearrange the equation to solve for frequency.\n\\(f = \\frac{c}{\\lambda}\\)","solution":"Substitute the values for the speed of light and wavelength into the equation.\n\\(f = \\frac{3.00\\, \\times \\,{10}^{8}\\text{m/s}}{6.00\\, \\times \\,{10}^{- 7}\\text{m}} = 5.00\\, \\times \\,{10}^{14}{\\text{s}}^{- 1} = 5.00\\, \\times \\,{10}^{14}\\text{Hz}\\)","solutionImages":[],"solutionTables":[],"discussion":"Manipulating exponents of 10 in a fraction can be tricky. Be sure you keep track of the + and – exponents correctly. Checking back to the diagram of the electromagnetic spectrum in the previous section shows that 10 14 is a reasonable order of magnitude for the frequency of yellow light.\nThe frequency of a wave is proportional to the energy the wave carries. The actual proportionality constant will be discussed in a later chapter. Since frequency is inversely proportional to wavelength, we also know that wavelength is inversely proportional to energy. Keep these relationships in mind as general rules."},{"uid":"hsphys.ch15.sec02.ex02","number":"15.2.2","title":"Calculating Illuminance","problem":"A woman puts a new bulb in a floor lamp beside an easy chair. If the luminous flux of the bulb is rated at 2,000 lm, what is the illuminance on a book held 2.00 m from the bulb?","problemImages":[],"strategy":"Choose the equation and list the knowns.\nEquation:\n\\(\\text{illuminance =}\\,\\frac{P}{4\\pi {r}^{2}}\\)\nP = 2,000 lm\nπ = 3.14\nr = 2.00 m","solution":"Substitute the known values into the equation.\n\\(\\text{illuminance}\\text{=}\\frac{P}{4\\pi {r}^{2}}\\text{=}\\frac{\\text{2,000}\\text{lm}}{4(3.14){(2.00)}^{2}{\\text{m}}^{2}}\\text{=}39.8{\\text{lm/m}}^{2}\\text{=}39.8\\,\\text{lx}\\)","solutionImages":[],"solutionTables":[],"discussion":"Try some other distances to illustrate how greatly light fades with distance from its source. For example, at 3 m the illuminance is only 17.7 lux. Parents often scold children for reading in light that is too dim. Instead of shouting, “You’ll ruin your eyes!” it might be better to explain the inverse square law of illuminance to the child."}],"snapLabs":[{"uid":"hsphys.ch15.sec02.lab01","title":"Polarized Glasses","text":"EYE SAFETY—Looking at the Sun directly can cause permanent eye damage. Avoid looking directly at the Sun.\ntwo pairs of polarized sunglasses\nOR\ntwo lenses from one pair of polarized sunglasses\nProcedure\nLook through both or either polarized lens and record your observations.\nHold the lenses, one in front of the other. Hold one lens stationary while you slowly rotate the other lens. Record your observations, including the relative angles of the lenses when you make each observation.\nFind a reflective surface on which the Sun is shining. It could be water, glass, a mirror, or any other similar smooth surface. The results will be more dramatic if the sunlight strikes the surface at a sharp angle.\nObserve the appearance of the surface with your naked eye and through one of the polarized lenses.\nObserve any changes as you slowly rotate the lens, and note the angles at which you see changes.","images":[]}],"tipsAndFeatures":[],"summaryPoints":["EM radiation travels at different speeds in different media, produces colors on thin films, and can be polarized to oscillate in only one direction.","Calculations can be based on the relationship among the speed, frequency, and wavelength of light, and on the relationship among luminous flux, illuminance, and distance."],"glossary":[{"term":"illuminance","termVi":"Độ rọi (E_v)","definition":"number of lumens per square meter, given in units of lux (lx)","definitionVi":"Quang thông chiếu vuông góc lên một đơn vị diện tích bề mặt (đơn vị Lux, lx): E = P / (4πr²).","memoryTipVi":"Tỉ lệ nghịch với bình phương khoảng cách r² từ nguồn sáng."},{"term":"interference","termVi":"Sự giao thoa ánh sáng","definition":"increased or decreased light intensity caused by the phase differences between waves","definitionVi":"Hiện tượng hai chùm sáng kết hợp chồng chất lên nhau tạo các vân sáng – tối xen kẽ.","memoryTipVi":"Bằng chứng khẳng định bản chất sóng của ánh sáng."},{"term":"lumens","termVi":"Lumen (lm)","definition":"unit of measure for luminous flux","definitionVi":"Đơn vị SI đo Quang thông (tổng lượng ánh sáng nhìn thấy phát ra từ nguồn).","memoryTipVi":"Khi mua bóng đèn LED, xem chỉ số Lumen để biết độ sáng thật!"},{"term":"luminous flux","termVi":"Quang thông (P)","definition":"rate at which light is radiated from a source","definitionVi":"Tổng năng lượng ánh sáng nhìn thấy mà nguồn phát ra trong 1 giây (đơn vị Lumen, lm).","memoryTipVi":"Đo độ sáng tổng thể của bóng đèn."},{"term":"lux","termVi":"Lắc (lx)","definition":"unit of measure for illuminance","definitionVi":"Đơn vị SI đo Độ rọi: 1 lx = 1 lm/m².","memoryTipVi":"Đo độ sáng nhận được trên mặt bàn học."},{"term":"polarized light","termVi":"Ánh sáng phân cực","definition":"light whose electric field component vibrates in a specific plane","definitionVi":"Ánh sáng mà vectơ điện trường chỉ dao động theo một phương duy nhất (ứng dụng làm kính râm chống chói).","memoryTipVi":"Chỉ có SÓNG NGANG mới có thể phân cực!"}],"assessments":[{"uid":"hsphys.ch15.sec02.q001","sourceId":"fs-id1167063891863","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Give an example of a place where light travels at the speed of 3.00 × 10 8 m/s.","images":[],"choices":[{"label":"a","text":"outer space"},{"label":"b","text":"water"},{"label":"c","text":"Earth’s atmosphere"},{"label":"d","text":"quartz glass"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q002","sourceId":"fs-id1167063415383","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Explain in terms of distances and the speed of light why it is currently very unlikely that humans will visit planets that circle stars other than our Sun.","images":[],"choices":[{"label":"a","text":"The spacecrafts used for travel are very heavy and thus very slow."},{"label":"b","text":"Spacecrafts do not have a constant source of energy to run them."},{"label":"c","text":"If a spacecraft could attain a maximum speed equal to that of light, it would still be too slow to cover astronomical distances."},{"label":"d","text":"Spacecrafts can attain a maximum speed equal to that of light, but it is difficult to locate planets around stars."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q003","sourceId":"fs-id1167063526786","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Red light has a wavelength of 7.0 × 10-7 m and a frequency of 4.3 × 1014 Hz. Use these values to calculate the speed of light in a vacuum.","images":[],"choices":[{"label":"a","text":"3 × 1020 m/s"},{"label":"b","text":"3 × 1015 m/s"},{"label":"c","text":"3 × 1014 m/s"},{"label":"d","text":"3 × 108 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q005","sourceId":"fs-id1167067198400","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Light travels at different speeds in different media. Put these media in order, from the slowest light speed to the fastest light speed: air, diamond, vacuum, water.","images":[],"choices":[{"label":"a","text":"diamond, water, air, vacuum"},{"label":"b","text":"vacuum, diamond, air, water"},{"label":"c","text":"diamond, air, water, vacuum"},{"label":"d","text":"air, diamond, water, vacuum"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q007","sourceId":"eip-id1166849941050","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Bright sunlight is reflected from an icy pond. You look at the glare of the reflected light through polarized glasses. When you take the glasses off, rotate them 90°, and look through one of the lenses again, the light you see becomes brighter. Explain why the light you see changes.","images":[],"choices":[{"label":"a","text":"The glass blocks horizontally polarized light, and the light reflected from the icy pond is, in part, polarized horizontally."},{"label":"b","text":"The glass blocks vertically polarized light, and the light reflected from the icy pond is, in part, polarized vertically."},{"label":"c","text":"The glass allows horizontally polarized light to pass, and the light reflected from the icy pond is, in part, polarized vertically."},{"label":"d","text":"The glass allows horizontally polarized light to pass, and the light reflected from the icy pond is, in part, polarized horizontally."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q008","sourceId":"fs-id1167063582982","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Explain how thin-film interference occurs. Discuss in terms of the meaning of interference and the pathways of light waves.","images":[],"choices":[{"label":"a","text":"For a particular thickness of film, light of a given wavelength that reflects from the outer and inner film surfaces is completely in phase, and so undergoes constructive interference."},{"label":"b","text":"For a particular thickness of film, light of a given wavelength that reflects from the outer and inner surfaces is completely in phase, and so undergoes destructive interference."},{"label":"c","text":"For a particular thickness of film, light of a given wavelength that reflects from the outer and inner film surfaces is completely out of phase, and so undergoes constructive interference."},{"label":"d","text":"For a particular thickness of film, light of a given wavelength that reflects from the outer and inner film surfaces is completely out of phase, and so undergoes no interference."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q009","sourceId":"eip-id1166849297320","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"When you move a rope up and down, waves are created. If the waves pass through a slot, they will be affected differently, depending on the orientation of the slot. Using the rope waves and the slot as a model, explain how polarizing glasses affect light waves.","images":[],"choices":[{"label":"a","text":"If the wave—electric field—is vertical and slit—polarizing molecules in the glass—is horizontal, the wave will pass."},{"label":"b","text":"If the wave—electric field— is vertical and slit—polarizing molecules in the glass—is vertical, the wave will not pass."},{"label":"c","text":"If the wave—electric field—is horizontal and slit—polarizing molecules in the glass—is horizontal, the wave will pass."},{"label":"d","text":"If the wave—electric field—is horizontal and slit—polarizing molecules in the glass—is horizontal, the wave will not pass."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q010","sourceId":"fs-id1167063526786","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Red light has a wavelength of 7.0 × 10-7 m and a frequency of 4.3 × 1014 Hz. Use these values to calculate the speed of light in a vacuum.","images":[],"choices":[{"label":"a","text":"3 × 1020 m/s"},{"label":"b","text":"3 × 1015 m/s"},{"label":"c","text":"3 × 1014 m/s"},{"label":"d","text":"3 × 108 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q012","sourceId":"fs-id1167066848542","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Visible light has a range of wavelengths from about 400 nm to 800 nm . What is the range of frequencies for visible light?","images":[],"choices":[{"label":"a","text":"3.75 × 10 6 Hz to 7.50 × 10 6 Hz"},{"label":"b","text":"3.75 Hz to 7.50 Hz"},{"label":"c","text":"3.75 × 10 -7 Hz to 7.50 × 10 -7 Hz"},{"label":"d","text":"3.75 × 10 14 Hz to 7.50 × 10 14 Hz"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q013","sourceId":"fs-id1167063915153","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Light travels through the wall of a soap bubble that is 600 nm thick and is reflected from the inner surface back into the air. Assume the bubble wall is mostly water and that light travels in water at 75 percent of the speed of light in vacuum. How many seconds behind will the light reflected from the inner surface arrive compared to the light that was reflected from the outer surface?","images":[],"choices":[{"label":"a","text":"4.0 × 10 –8 s"},{"label":"b","text":"5.3 × 10 –6 s"},{"label":"c","text":"2.65 × 10 –15 s"},{"label":"d","text":"5.3 × 10 –15 s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q014","sourceId":"fs-id1167061322379","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"To compare the brightness of light bulbs for sale in a store, you should look on the labels to see how they are rated in terms of ____.","images":[],"choices":[{"label":"a","text":"frequency"},{"label":"b","text":"watts"},{"label":"c","text":"amps"},{"label":"d","text":"lumens"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q015","sourceId":"fs-id1167067217170","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the wavelength of red light with a frequency of 4.00 × 10 14 Hz?","images":[],"choices":[{"label":"a","text":"2.50 × 10 14 m"},{"label":"b","text":"4.00 × 10 15 m"},{"label":"c","text":"2.50 × 10 6 m"},{"label":"d","text":"7.50 × 10 -7 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q016","sourceId":"eip-id1166849964785","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the distance of one light year in kilometers?","images":[],"choices":[{"label":"a","text":"2.59 × 10 10 km"},{"label":"b","text":"1.58 × 10 11 km"},{"label":"c","text":"2.63 × 10 9 km"},{"label":"d","text":"9.46 × 10 12 km"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q017","sourceId":"eip-id1166849976101","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"How does the illuminance of light change when the distance from the light source is tripled? Cite the relevant equation and explain how it supports your answer.","images":[],"choices":[{"label":"a","text":"Illuminance = \nP\n4 π\nr\n2\n; if distance is tripled, then the illuminance increases by 19 times."},{"label":"b","text":"Illuminance = \nP\n4 π\nr\n; if distance is tripled, then the illuminance decreases by 13 times."},{"label":"c","text":"Illuminance =  P · 4 π\nr\n2\n; if distance is tripled, then the illuminance decreases by 9 times."},{"label":"d","text":"Illuminance =  P · 4 π\nr\n; if distance tripled, then the illuminance increases by 3 times."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q018","sourceId":"eip-id1166850196399","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A light bulb has an illuminance of 19.9 lx at a distance of 2 m . What is the luminous flux of the bulb?","images":[],"choices":[{"label":"a","text":"500 lm"},{"label":"b","text":"320 lm"},{"label":"c","text":"250 lm"},{"label":"d","text":"1,000 lm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q019","sourceId":"fs-id1167063687579","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Describe what happens to the path of light when the light slows down as it passes from one medium to another?","images":[],"choices":[{"label":"a","text":"The path of the light remains the same."},{"label":"b","text":"The path of the light becomes circular."},{"label":"c","text":"The path of the light becomes curved."},{"label":"d","text":"The path of the light changes."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q021","sourceId":"fs-id1167063864807","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How many lumens are radiated from a candle which has an illuminance of 3.98 lx at a distance of 2.00 m?","images":[],"choices":[{"label":"a","text":"400 lm"},{"label":"b","text":"100 lm"},{"label":"c","text":"50 lm"},{"label":"d","text":"200 lm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q022","sourceId":"fs-id1167061216890","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Saturn is 1.43×1012 m from the Sun. How many minutes does it take the Sun’s light to reach Saturn?","images":[],"choices":[{"label":"a","text":"7.94 × 10 9 minutes"},{"label":"b","text":"3.4 × 10 4 minutes"},{"label":"c","text":"3.4 × 10 –6 minutes"},{"label":"d","text":"79.4 minutes"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch15.sec02.q023","sourceId":"fs-id1167066953213","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Explain why we see the colorful effects of thin-film interference on the surface of soap bubbles and oil slicks, but not on the surface of a window pane or clear plastic bag.","images":[],"choices":[{"label":"a","text":"The thickness of a window pane or plastic bag is more than the wavelength of light, and interference occurs for thicknesses smaller than the wavelength of light."},{"label":"b","text":"The thickness of a window pane or plastic bag is less than the wavelength of light, and interference occurs for thicknesses similar to the wavelength of light."},{"label":"c","text":"The thickness of a window pane or plastic bag is more than the wavelength of light, and interference occurs for thicknesses similar to the wavelength of light."},{"label":"d","text":"The thickness of a window pane or plastic bag is less than the wavelength of light, and interference occurs for thicknesses larger than the wavelength of light."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":2,"subsectionCount":3,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":6,"assessmentCount":19}}],"summary":{"totalSections":3,"totalKeyEquations":2,"totalWorkedExamples":2,"totalSnapLabs":1,"totalGlossaryTerms":10,"totalAssessments":33,"referencedMediaCount":12},"qualityGate":{"passed":true,"checkedUids":45,"errors":[],"warnings":[]}};
